/**
 * Produces `fixtures/example-annotated.pdf` - the worked example the assignment asks
 * for. Runs the whole pipeline offline (extract -> grade -> anchor -> annotate) so the
 * artefact can be regenerated by anyone without an API key.
 *
 *   npm run example
 */

import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadRubric } from "../server/src/domain/rubric.js";
import { gradeAnswer } from "../server/src/services/grading/grader.js";
import { MockGrader } from "../server/src/services/llm/mock.js";
import { buildAnnotatedPdf } from "../server/src/services/pdf/annotatePdf.js";
import { extractPdf } from "../server/src/services/pdf/extractText.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const FIXTURES = path.resolve(here, "..", "fixtures");

const source = process.argv[2] ?? path.join(FIXTURES, "student-answer.pdf");
const target = process.argv[3] ?? path.join(FIXTURES, "example-annotated.pdf");

const bytes = await fs.readFile(source);
const [answerDoc, rubric] = await Promise.all([extractPdf(bytes), loadRubric()]);

const { result, annotations } = await gradeAnswer({
  rubric,
  answerDoc,
  answerPdf: bytes,
  answerFilename: path.basename(source),
  documents: { answerId: "example" },
  provider: new MockGrader(),
});

const annotated = await buildAnnotatedPdf(bytes, result, annotations);
await fs.writeFile(target, annotated);

console.log(`Graded ${path.basename(source)}: ${result.totalMarks}/${result.maxMarks}`);
console.log(
  `  ${annotations.length} annotations (${annotations.filter((a) => a.anchored).length} placed on the page)`,
);
console.log(`  wrote ${path.relative(process.cwd(), target)}`);

// The original must be untouched: verify rather than assume.
const after = await fs.readFile(source);
if (Buffer.compare(bytes, after) !== 0) {
  throw new Error("The original answer paper was modified - this must never happen.");
}
console.log("  original answer paper verified unchanged");
